const onTick = ({ ratio }: TickEvent) => {
  if (idle) return;
  const dt = Math.min(ratio / 60, MAX_DT);
  const steps = Math.max(1, Math.ceil(dt / SUBSTEP));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    v += (STIFFNESS * (target - x) - DRAG * v) * h;
    x += v * h;
  }
  if (Math.abs(target - x) < 0.0005 && Math.abs(v) < 0.005) {
    x = target;
    v = 0;
    setIdle(true);
  }
  apply();
};

